"use client"; // 클라이언트 측에서만 실행되도록 명시

import React, { useState, useEffect } from 'react';
import { getToken, getUserInfo } from "../../../token";  // getToken과 getUserInfo를 token.ts에서 가져옴

const Modal = ({ isOpen, onClose }) => {
  const [userInfo, setUserInfo] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!isOpen) return;  // 모달이 열릴 때만 실행

    const fetchUserData = async () => {
      try {
        const token = await getToken(); // getToken을 통해 토큰을 가져옴
        if (token) {
          const user = await getUserInfo(); // getUserInfo로 사용자 정보 요청
          setUserInfo(user); // 사용자 정보 저장
        } else {
          console.error('토큰이 유효하지 않습니다.');
        }
      } catch (error) {
        console.error('사용자 정보를 가져오는 데 실패했습니다:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchUserData();
  }, [isOpen]); // 모달이 열릴 때마다 API 호출

  if (!isOpen) return null; // 모달이 닫히면 아무것도 렌더링하지 않음

  return (
    <div className={styles.modalOverlay}>
      <div className={styles.modalContent}>
        <div className={styles.modalHeader}>
          <span className={styles.close} onClick={onClose}>
            &times;
          </span>
          <h2>Modal Header</h2>
        </div>
        <div className={styles.modalBody}>
          {loading ? (
            <p>Loading...</p>
          ) : userInfo ? (
            <>
              <p>User ID: {userInfo.id}</p>
              <p>Name: {userInfo.name}</p>
              <p>Email: {userInfo.email}</p>
              <p>Nickname: {userInfo.nickname}</p>
              <p>Membership ID: {userInfo.membershipId}</p>
            </>
          ) : (
            <p>Failed to fetch user data.</p>
          )}
        </div>
        <div className={styles.modalFooter}>
          <h3>Modal Footer</h3>
        </div>
      </div>
    </div>
  );
};

export default Modal;
